SELECT qryTrustReportRPT.CaseID, qryTrustReportRPT.Case_Letter, qryTrustReportRPT.yr, qryTrustReportRPT.Number_, qryTrustReportRPT.Orig_Atty, qryTrustReportRPT.Matter_type, qryTrustReportRPT.CaseOpenDate, Sum(qryTrustReportRPT.Balance) AS SumOfBalance, qryTrustReportRPT.CheckCashed, qryTrustReportRPT.CaseNo, qryTrustReportRPT.Last_Name, qryTrustReportRPT.First_Name
FROM (qryTrustReportRPT LEFT JOIN tblCase ON qryTrustReportRPT.CaseID = tblCase.CaseID) LEFT JOIN qryTrustAccount ON qryTrustReportRPT.TrustAccountID = qryTrustAccount.TrustAccountID
GROUP BY qryTrustReportRPT.CaseID, qryTrustReportRPT.Case_Letter, qryTrustReportRPT.yr, qryTrustReportRPT.Number_, qryTrustReportRPT.Orig_Atty, qryTrustReportRPT.Matter_type, qryTrustReportRPT.CaseOpenDate, qryTrustReportRPT.CheckCashed, qryTrustReportRPT.CaseNo, qryTrustReportRPT.Last_Name, qryTrustReportRPT.First_Name;